import{_ as e,o as d,c as r,ae as a}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"視覺品質規劃 — taste-skill 參考評估與引入提案","description":"","frontmatter":{},"headers":[],"relativePath":"product/visual-quality-plan.md","filePath":"product/visual-quality-plan.md"}'),o={name:"product/visual-quality-plan.md"};function s(i,t,n,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="視覺品質規劃-—-taste-skill-參考評估與引入提案" tabindex="-1">視覺品質規劃 — taste-skill 參考評估與引入提案 <a class="header-anchor" href="#視覺品質規劃-—-taste-skill-參考評估與引入提案" aria-label="Permalink to &quot;視覺品質規劃 — taste-skill 參考評估與引入提案&quot;">​</a></h1><blockquote><p>建立日：2026-07-08 · 狀態：<strong>§2.A 已採用定版</strong>（→ <a href="./ui-review-checklist.html">ui-review-checklist.md</a>）；§8 D2–D5 討論中 參考來源：<a href="https://github.com/Leonxlnx/taste-skill" target="_blank" rel="noreferrer">Leonxlnx/taste-skill</a>（<code>design-taste-frontend</code> v2 experimental，SKILL.md 1206 行全文已審閱） 定位原則：<strong>taste-skill 是參考意見，不是開發標準</strong>。產品規格 SSOT 仍是 <code>specs/</code> + <a href="./interface-roadmap.html">interface-roadmap.md</a>；視覺 token SSOT 仍是 explore-design-sdk。本文件只決定「哪些意見值得內化為自有規格」。</p></blockquote><hr><h2 id="_0-定位決策-建議" tabindex="-1">0. 定位決策（建議） <a class="header-anchor" href="#_0-定位決策-建議" aria-label="Permalink to &quot;0. 定位決策（建議）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>SSOT</th><th>taste-skill 的角色</th></tr></thead><tbody><tr><td>產品規格／契約</td><td><code>specs/openapi</code>、<code>specs/policies</code>、interface-roadmap</td><td>無角色（out of scope，其自述亦然）</td></tr><tr><td>設計 token／主題</td><td>explore-design-sdk（PALETTE.md、application maps）</td><td>無角色；不得覆寫 token 決策</td></tr><tr><td>版面品質／反模板</td><td><strong>本文件的 checklist（自有、在地化）</strong></td><td>素材來源：萃取規則，標注出處</td></tr><tr><td>Agent 產 UI 工作流</td><td>AGENTS.md / <code>.cursor/skills</code></td><td>可選：僅對 marketing/developer surface 掛用</td></tr></tbody></table><p><strong>不建議</strong> <code>npx skills add</code> 裝成全域規則：v2 為 pre-release、其設計對象是 landing/portfolio、且我們要的是「參考意見而非固定模板」。做法改為<strong>萃取內化</strong>——把通過討論的規則寫進自有 checklist，保留出處以便追蹤上游更新。</p><hr><h2 id="_1-surface-分區-套用範圍的前提" tabindex="-1">1. Surface 分區（套用範圍的前提） <a class="header-anchor" href="#_1-surface-分區-套用範圍的前提" aria-label="Permalink to &quot;1. Surface 分區（套用範圍的前提）&quot;">​</a></h2><p>依 taste-skill 自身的 out-of-scope 聲明（dashboards、dense product UI、data tables、multi-step forms 明列不適用），先為 sitemap 每頁標注 surface：</p><table tabindex="0"><thead><tr><th>頁面</th><th>Surface</th><th>taste-skill 適用度</th></tr></thead><tbody><tr><td><code>/</code>（chat 預設）</td><td>product + marketing 混合</td><td>中高：empty = marketing 首屏；active conversation 走 product checklist（反空卡／四態／composer）</td></tr><tr><td><code>/?view=dashboard</code></td><td>data surface</td><td>低：只取反 fake-UI／反裝飾原則當 review 項</td></tr><tr><td><code>/catalog-search</code>、<code>/metadata</code></td><td>product/data surface</td><td>低到中：列表節奏、empty/loading 態可參考；資訊架構不動</td></tr><tr><td><code>/items</code>、表單</td><td>product surface</td><td>低：表單規則已有（label 上、error 下）與其一致</td></tr><tr><td><code>/dishes</code>、<code>/recipes</code>（列表/詳情）</td><td>marketing-ish（dataset landing）</td><td>中：敘事與版面家族多樣性可參考</td></tr><tr><td><code>/developers</code> 總覽、SDK quick start</td><td>developer surface</td><td>中高：最適合套的區域</td></tr><tr><td><code>/developers/apis/:apiId</code>（三欄 try-it）</td><td>dense product UI</td><td>低：明確 out of scope</td></tr><tr><td><code>/insights</code></td><td>data surface</td><td>低</td></tr><tr><td><code>/release-notes</code>、對外 landing/docs intro</td><td>marketing surface</td><td>高</td></tr></tbody></table><hr><h2 id="_2-引入清單-逐項待議" tabindex="-1">2. 引入清單（逐項待議） <a class="header-anchor" href="#_2-引入清單-逐項待議" aria-label="Permalink to &quot;2. 引入清單（逐項待議）&quot;">​</a></h2><h3 id="_2-a-建議「直接採用」-surface-無關、與現有規格相容" tabindex="-1">2.A 建議「直接採用」（surface 無關、與現有規格相容） <a class="header-anchor" href="#_2-a-建議「直接採用」-surface-無關、與現有規格相容" aria-label="Permalink to &quot;2.A 建議「直接採用」（surface 無關、與現有規格相容）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>規則（出處：SKILL.md 章節）</th><th>落點</th></tr></thead><tbody><tr><td>A1</td><td><strong>四態完整性</strong>：每個資料畫面必備 loading（形狀吻合 skeleton）/ empty / error / tactile feedback（§4.5）</td><td>DESIGN_SYSTEM.md + M6 E2E 驗收項；SDK ux tier（Skeleton/EmptyState）已備</td></tr><tr><td>A2</td><td><strong>對比三檢</strong>：Button/Form/CTA 全過 WCAG AA（4.5:1，大字 3:1）；照片底按鈕需 scrim（§4.6）</td><td>DESIGN_SYSTEM.md review checklist</td></tr><tr><td>A3</td><td><strong>三個 Lock</strong>：Page Theme Lock（頁面單主題不反轉）、Color Consistency Lock（accent 全頁一致）、Shape Consistency Lock（單一圓角系統）（§4.2/4.4）</td><td>與 SDK 單 map 供裝天然相容，寫成明文</td></tr><tr><td>A4</td><td><strong>反 fake-UI</strong>：禁 div 假截圖、假精確數字（無來源的 92%）、假 logo 牆、假 avatar/人名（§9.D/9.E）</td><td>review checklist；demo 資料一律標注 mock</td></tr><tr><td>A5</td><td><strong>Motion motivated</strong>：每個動畫能一句話說出目的；<code>prefers-reduced-motion</code> 預設尊重；禁 <code>window.addEventListener(&#39;scroll&#39;)</code>（§5）</td><td>DESIGN_SYSTEM.md；SDK motion tokens 補用途註記</td></tr><tr><td>A6</td><td><strong>Copy self-audit</strong>：出貨前重讀所有可見字串，刪 AI 腔（Elevate/Seamless 類 filler verbs 的中文對應：「賦能」「極致」「重新定義」）（§4.10/9.D）</td><td>review checklist（在地化詞表）</td></tr><tr><td>A7</td><td><strong>版面家族反重複</strong>：同 layout family 每頁最多一次；左右交錯最多連續 2 段（§4.7）</td><td>marketing/developer surface 的 checklist 項</td></tr><tr><td>A8</td><td><strong>Redesign 先 audit</strong>：改版前記錄 brand tokens / IA / 保留與淘汰清單 + 現況 dial 估值；現代化槓桿順序 typography → spacing → color → motion → hero 重組（§11）</td><td><strong>直接用於 R1 排版改善的執行順序</strong>（見 §5）</td></tr></tbody></table><h3 id="_2-b-建議「改造後採用」-需在地化或映射到-token" tabindex="-1">2.B 建議「改造後採用」（需在地化或映射到 token） <a class="header-anchor" href="#_2-b-建議「改造後採用」-需在地化或映射到-token" aria-label="Permalink to &quot;2.B 建議「改造後採用」（需在地化或映射到 token）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>原規則</th><th>改造提案</th></tr></thead><tbody><tr><td>B1</td><td>三 dials（DESIGN_VARIANCE / MOTION_INTENSITY / VISUAL_DENSITY）</td><td>不引入 dial 機制本身，改為 <strong>per-surface preset</strong> 映射到 SDK spacing/motion token（見 §4）；密度變化＝換 token 值，不是換規則</td></tr><tr><td>B2</td><td>Design Read（產 UI 前一行宣告 page kind/audience/vibe）</td><td>納入 agent 工作流：產 UI 前輸出 design read + <strong>surface tag</strong>；模糊時只問一題</td></tr><tr><td>B3</td><td>Pre-flight check（60 項）</td><td>裁剪為 <strong>20 項左右自有 checklist</strong>（§6 草案），去除 landing 專屬項（hero 20 字上限等只掛 marketing surface）</td></tr><tr><td>B4</td><td>Em-dash ban</td><td>英文文案適用；<strong>中文在地化</strong>：規範全形標點、禁英文 em-dash 混入中文、行長以字數計（body 35–42 全形字）</td></tr><tr><td>B5</td><td>Eyebrow restraint（每 3 section 最多 1 個 uppercase 小標）</td><td>marketing surface 採用；product surface 的欄位標籤不受限</td></tr><tr><td>B6</td><td>每 section 預設形狀（短標題 ≤8 字 + 短段落 ≤25 字 + 一個視覺或 CTA）</td><td>中文化字數（標題 ≤12 全形字、段落 ≤40 全形字），掛 marketing/developer surface</td></tr></tbody></table><h3 id="_2-c-建議「不採用」-與現有體系衝突或不適用" tabindex="-1">2.C 建議「不採用」（與現有體系衝突或不適用） <a class="header-anchor" href="#_2-c-建議「不採用」-與現有體系衝突或不適用" aria-label="Permalink to &quot;2.C 建議「不採用」（與現有體系衝突或不適用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>原規則</th><th>不採用理由</th></tr></thead><tbody><tr><td>C1</td><td>Design system mapping 表（Fluent/Carbon/Polaris…）</td><td>我們有自有 SDK；後台標準已定 Untitled UI（portal-untitled map）</td></tr><tr><td>C2</td><td>Stack 預設（Next.js RSC + Motion + GSAP）</td><td>本 repo 是 Remix/React Router；動效走自有 motion tokens 與 vue-motion promote 路徑</td></tr><tr><td>C3</td><td>Serif-as-default ban、Fraunces 禁用</td><td>我們的和紙編輯風 serif display 是<strong>明文品牌決策</strong>（PALETTE.md + S2.6 token），正屬其自己允許的例外（brand-mandated editorial）；不因此換字體</td></tr><tr><td>C4</td><td>Premium beige+brass palette ban</td><td>我們暖色盤出自和色體系 + Realtime Colors 明示選擇，非 AI 慣性 default；但<strong>接受其精神</strong>：新增主題時做 palette-rotation 檢查（不連續產出同族米金）</td></tr><tr><td>C5</td><td>Inter 避用、lucide-react discouraged</td><td>body 用 Inter 屬其允許的 neutral 案例；icon 換族成本高收益低。列為 open question 不強制</td></tr><tr><td>C6</td><td>image-gen 參考圖流程（imagegen-* skills）</td><td>領域是 mock-first 產品 UI，非 marketing 素材產線；需要時個案處理</td></tr></tbody></table><hr><h2 id="_3-衝突點備忘-討論用" tabindex="-1">3. 衝突點備忘（討論用） <a class="header-anchor" href="#_3-衝突點備忘-討論用" aria-label="Permalink to &quot;3. 衝突點備忘（討論用）&quot;">​</a></h2><ol><li><strong>serif 與暖色</strong>：taste-skill 把「創意案就上 serif／米金色」列為頭號 AI-tell。我們的組合之所以成立，是因為它有<strong>體系出處</strong>（和色、PALETTE.md、token 三層）與<strong>一致執行</strong>（全站單一主題 lock）。結論方向：把「有意圖的證據」寫進 DESIGN_SYSTEM.md，反模板的重點是「不無意識地選」，不是「不准選」。</li><li><strong>它的 anti-default 精神與我們的 token 體系同構</strong>：它反對的是「跳過 brief 直接套 LLM 預設美學」；我們反對的是「跳過 token 直接寫死色值」。兩者可以合併成一條原則：<strong>所有視覺決策都要有可追溯的出處（brief 或 token）</strong>。</li><li><strong>dashboard/資料介面</strong>它自己讓位：density 8-10 檔的建議（1px 分線、<code>font-mono</code> 數字、無卡片框）反而值得 <code>/insights</code> 與 API explorer 參考——這是它 out-of-scope 區裡少數可撿的具體意見。</li></ol><hr><h2 id="_4-per-surface-preset-提案-dial-→-token-映射" tabindex="-1">4. Per-surface preset 提案（dial → token 映射） <a class="header-anchor" href="#_4-per-surface-preset-提案-dial-→-token-映射" aria-label="Permalink to &quot;4. Per-surface preset 提案（dial → token 映射）&quot;">​</a></h2><p>不引入 dial 數字，改用語意 preset（值 = SDK token）：</p><table tabindex="0"><thead><tr><th>Surface</th><th>版面變化</th><th>動效</th><th>密度（space.section / stack）</th><th>備註</th></tr></thead><tbody><tr><td>marketing（landing、release-notes、dataset landing）</td><td>中高（非對稱可用）</td><td>中（motivated only）</td><td>寬鬆 4rem / 1.25rem（portal map 現值）</td><td>和紙編輯風完整表達</td></tr><tr><td>chat 首頁</td><td>中</td><td>低中</td><td>empty 寬鬆；conversation 標準</td><td>empty = 敘事 + 單一 composer；active = 文件寬 turn，無空卡</td></tr><tr><td>product（catalog/metadata/items）</td><td>低（可預期優先）</td><td>低</td><td>標準 3rem / 1rem（enterprise 值）</td><td>一致性 &gt; 個性</td></tr><tr><td>data（insights、dashboard 總覽）</td><td>低</td><td>低</td><td>緊湊（提案新增 <code>space.section</code> 緊湊檔 2rem；數字 <code>font-mono</code>、1px 分線、少卡片）</td><td>取自 density 8-10 檔建議</td></tr><tr><td>developer（/developers 總覽、SDK docs）</td><td>中</td><td>低中</td><td>標準</td><td>文件可讀性優先，行寬 ≤ 65ch/40 全形字</td></tr></tbody></table><p>→ 若同意，落地方式：SDK 增加 <code>portal-dense</code>（或 semantic 加 <code>space.section-dense</code>）供 data surface 用；不新增 dial 概念。</p><hr><h2 id="_5-r1-排版改善的執行順序-採-redesign-protocol" tabindex="-1">5. R1 排版改善的執行順序（採 redesign protocol） <a class="header-anchor" href="#_5-r1-排版改善的執行順序-採-redesign-protocol" aria-label="Permalink to &quot;5. R1 排版改善的執行順序（採 redesign protocol）&quot;">​</a></h2><p>「介面排版不順眼」的處理採其現代化槓桿順序，先 audit 後動手：</p><ol><li><strong>Audit</strong>：對現有每頁記錄——用了哪些 token、哪些寫死值、layout family 重複處、四態缺漏、surface tag。</li><li><strong>Typography</strong>（風險最低、視覺提升最大）：display/body token 已入（S2.6），逐頁套 <code>font-display</code> 與行寬上限。</li><li><strong>Spacing &amp; rhythm</strong>：以 <code>space.section/stack/gutter</code> 統一節奏（目前鬆散感主因）。</li><li><strong>Color 校準</strong>：檢查 Color Consistency Lock（有無 section 級走鐘）。</li><li><strong>Motion 層</strong>：僅 motivated 動效。</li><li><strong>關鍵 section 重組</strong>：最後才動結構（sidebar、首頁 hero）。</li></ol><hr><h2 id="_6-ui-review-checklist-草案-v0-在地化-待議後定版" tabindex="-1">6. UI Review Checklist 草案 v0（在地化，待議後定版） <a class="header-anchor" href="#_6-ui-review-checklist-草案-v0-在地化-待議後定版" aria-label="Permalink to &quot;6. UI Review Checklist 草案 v0（在地化，待議後定版）&quot;">​</a></h2><p><strong>全 surface 通用</strong></p><ul><li>[ ] 視覺決策可追溯（token 或明文規格，無寫死色值/字級）</li><li>[ ] 單主題不反轉；accent 全頁一致；單一圓角系統</li><li>[ ] Button/Form/CTA 對比過 WCAG AA；焦點環可見</li><li>[ ] 四態齊備：loading（形狀吻合）/ empty / error / tactile</li><li>[ ] 無 fake UI：假截圖、無來源精確數字、假人名/頭像（mock 一律標注）</li><li>[ ] 動效皆有目的；尊重 <code>prefers-reduced-motion</code>；無 scroll listener</li><li>[ ] 中文排版：全形標點一致、無英文 em-dash 混入、body 行長 ≤ 42 全形字</li><li>[ ] 文案自審：刪「賦能／極致／重新定義／無縫」類 filler；一頁一種語氣</li><li>[ ] mobile 摺疊逐段明示；<code>min-h-[100dvh]</code></li><li>[ ] dark／light 兩模式皆檢視</li></ul><p><strong>marketing / developer surface 加驗</strong></p><ul><li>[ ] 首屏：標題 ≤ 2 行、說明 ≤ 40 全形字、CTA 免捲動</li><li>[ ] 同 layout family 每頁 ≤ 1；左右交錯 ≤ 連續 2 段</li><li>[ ] uppercase 小標每 3 section ≤ 1</li><li>[ ] CTA 語意不重複（同意圖同標籤）；logo/引用皆真實或標注</li></ul><p><strong>data surface 加驗</strong></p><ul><li>[ ] 數字 <code>font-mono</code>；分隔用 1px 線或留白，不堆卡片</li><li>[ ] 長清單換元件（分群/tabs/虛擬列表），不加長清單</li></ul><hr><h2 id="_7-藝術人文研究參考庫-提案-供排版發想" tabindex="-1">7. 藝術人文研究參考庫（提案，供排版發想） <a class="header-anchor" href="#_7-藝術人文研究參考庫-提案-供排版發想" aria-label="Permalink to &quot;7. 藝術人文研究參考庫（提案，供排版發想）&quot;">​</a></h2><p>規則管下限，參考養上限。建議在 SDK <code>docs/design-references.md</code> 增設研究庫，每次 surface 改版前做一頁研究筆記（3–5 個參考 + 為什麼 + 取什麼）：</p><p><strong>書（編輯與網格的根）</strong>：Josef Müller-Brockmann《Grid Systems in Graphic Design》、Emil Ruder《Typographie》、Jan Tschichold《The New Typography》、Robert Bringhurst《The Elements of Typographic Style》、原研哉《白》《Designing Design》、谷崎潤一郎《陰翳礼讃》（間・余白・陰影的美學基礎，直接支撐和紙編輯風）。</p><p><strong>站（持續巡）</strong>：<a href="https://japanwebdesign.com/" target="_blank" rel="noreferrer">Japan Web Design Gallery</a>（日系網站策展）、Fonts In Use（真實排版案例庫）、Letterform Archive（字體與印刷史料）、Typographica（字體評論）、The Gourmand / Kinfolk / Monocle（紙本編輯節奏）、MoMA / Cooper Hewitt（館藏數位化的資訊密度處理）、<a href="https://www.utsubo.com/blog/japanese-web-design-style-guide" target="_blank" rel="noreferrer">Utsubo 日系網頁設計指南</a>（Mincho 於 heritage/editorial 的使用脈絡）。</p><p><strong>用法</strong>：marketing surface 取編輯節奏與餘白；data surface 反向取 Monocle/館藏索引的高密度排法；developer surface 取 Fonts In Use 的規格式呈現。</p><hr><h2 id="_8-待議決策清單" tabindex="-1">8. 待議決策清單 <a class="header-anchor" href="#_8-待議決策清單" aria-label="Permalink to &quot;8. 待議決策清單&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>問題</th><th>建議</th></tr></thead><tbody><tr><td>D1</td><td><s>checklist v0（§6）定版？</s></td><td>✅ 2026-07-08 定版為 <a href="./ui-review-checklist.html">ui-review-checklist.md</a>，DESIGN_SYSTEM.md 已連結</td></tr><tr><td>D2</td><td><s>per-surface preset 是否落 SDK token？</s></td><td>✅ 2026-07-08：SDK semantic 加 <code>space.section-dense</code>（2rem）/<code>space.stack-dense</code>（0.75rem），enterprise 給值全主題繼承；portal tailwind 映射 <code>p-section-dense</code> 等</td></tr><tr><td>D3</td><td><s>Design Read 是否進 AGENTS.md？</s></td><td>✅ 2026-07-08：AGENTS.md「UI 產出規則」段——全 surface 標 tag；marketing/developer 必填一行 Design Read；出貨前過 checklist</td></tr><tr><td>D4</td><td><s>body 字型？</s></td><td>✅ 維持 Inter（+ Noto Sans TC fallback）：個性由 serif display 承擔，body 職責是中文混排穩定</td></tr><tr><td>D5</td><td><s>taste-skill 本體裝不裝？</s></td><td>✅ 不裝，用萃取版（ui-review-checklist.md）；v2.0.0 stable 後重新評估一次</td></tr><tr><td>D6</td><td><s>chat 互動流是否納入 checklist？</s></td><td>✅ 2026-08-14：conversation 為 product surface——無資料不畫空卡；LUI 依據內嵌於 assistant turn（T-2026-219）</td></tr></tbody></table>',47)])])}const u=e(o,[["render",s]]);export{g as __pageData,u as default};
